/* Test-only inputs for the actual original RenderScreen and candidate.
 * No expected image is generated by the optimization under test. */
__attribute__((visibility("default"))) unsigned d35_order_probe_hits_read(void)
{ return d35_order_probe_hits; }
__attribute__((visibility("default"))) unsigned d35_order_probe(unsigned seed,unsigned flags,unsigned warm,
 unsigned char *out,unsigned capacity)
{
 unsigned pitch=(flags&(4|128))?512:256,n=pitch*32,bytes=n*6+32;
 if(capacity<bytes)return 0;
 d35_order_probe_hits=0;
 PPU.BGMode=(flags&64)?0:1;PPU.BG3Priority=!(seed&512);
 PPU.ForcedBlanking=0;PPU.Mosaic=(flags&1)?3:1;
 PPU.Brightness=15;PPU.OBJSizeSelect=(seed&256)?3:0;
 PPU.OBJNameBase=0x8000;PPU.OBJNameSelect=0;PPU.FirstSprite=(seed>>2)&127;
 PPU.OAMPriorityRotation=!!(seed&256);PPU.OAMFlip=PPU.OAMAddr=PPU.OAMPriorityRotation;
 PPU.RangeTimeOver=0;
 memset(PPU.ClipWindow1Enable,0,sizeof(PPU.ClipWindow1Enable));
 memset(PPU.ClipWindow2Enable,0,sizeof(PPU.ClipWindow2Enable));
 memset(PPU.ClipWindow2Inside,0,sizeof(PPU.ClipWindow2Inside));
 memset(Memory.VRAM,0,65536);memset(Memory.FillRAM+0x2100,0,0x40);
 IPPU.DoubleWidthPixels=!!(flags&4);IPPU.DoubleHeightPixels=!!(flags&8);
 IPPU.HalfWidthPixels=!!(flags&16);IPPU.Interlace=0;IPPU.RenderedScreenWidth=pitch;
 IPPU.RenderedScreenHeight=32;IPPU.RenderThisFrame=1;
 GFX.PPL=pitch;GFX.PPLx2=pitch*2;GFX.Pitch=GFX.Pitch2=pitch*2;GFX.ZPitch=pitch;
 GFX.Pseudo=!!(flags&2);GFX.StartY=0;GFX.EndY=31;
 GFX.FixedColour=BUILD_PIXEL(7,13,19);
 static const unsigned math[8]={0,0x1f,0x5f,0x9f,0xdf,0x5f,0xdf,0};
 unsigned operation=(seed>>3)&7;
 GFX.r2131=math[operation];GFX.r2130=(operation==5||operation==6)?0:2;
 GFX.r212c=(flags&32)?0x13:0x17;GFX.r212d=(seed&256)?4:0x17;
 if(flags&32)GFX.r212d&=~4;
 Memory.FillRAM[0x212c]=GFX.r212c;Memory.FillRAM[0x212d]=GFX.r212d;
 Memory.FillRAM[0x2130]=GFX.r2130;Memory.FillRAM[0x2131]=GFX.r2131;
 if(!warm){memset(IPPU.TileCached[0],0,MAX_2BIT_TILES);memset(IPPU.TileCached[1],0,MAX_4BIT_TILES);memset(IPPU.TileCached[2],0,MAX_8BIT_TILES);}
 for(unsigned i=0;i<256;i++)IPPU.ScreenColors[i]=BUILD_PIXEL((i*3+1)&31,(i*7+3)&31,(i*11+5)&31);
 d35_color_palette_changed();
 for(unsigned bg=0;bg<4;bg++){
  unsigned bits=PPU.BGMode==0||bg>=2?2:4,base=bg*0x2000;
  PPU.BG[bg].NameBase=base/2;PPU.BG[bg].SCBase=0x3000+bg*0x400;
  PPU.BG[bg].SCSize=0;PPU.BG[bg].BGSize=seed&1;PPU.BGMosaic[bg]=(bg==2&&!!(flags&1));
  for(unsigned tile=0;tile<128;tile++)for(unsigned y=0;y<8;y++)for(unsigned x=0;x<8;x++){
   unsigned index=((tile+x*3+y*5+seed)&7)==0?0:1+(tile+x+y)%((1u<<bits)-1);
   for(unsigned bit=0;bit<bits;bit++)if(index&(1u<<bit))
    Memory.VRAM[(base+tile*(bits==2?16:32)+(bit/2)*16+y*2+(bit&1))&65535]|=1u<<(7-x);
  }
  for(unsigned t=0;t<1024;t++){
   unsigned tile=(t*3+bg*7)&63,priority=((t+bg+seed)>>1)&1;
   unsigned value=tile|(((t+bg)&7)<<10)|(priority<<13)|(((seed>>1)&3)<<14);
   WRITE_2BYTES(Memory.VRAM+(PPU.BG[bg].SCBase*2+t*2),value);
  }
  for(unsigned y=0;y<240;y++){LineData[y].BG[bg].VOffset=1+(seed&7);LineData[y].BG[bg].HOffset=(seed+bg*11+(y/8)*3)&31;}
 }
 /* OBJ data is independent of BG/map data, including transparent pixels. */
 for(unsigned i=0;i<0x4000;i++)Memory.VRAM[0x8000+i]=(i*37+seed*13)^(i>>5);
 for(unsigned i=0;i<128;i++){
  PPU.OBJ[i].HPos=i<((seed&256)?48:12)?(int)((i%12)*21)-9:300;
  PPU.OBJ[i].VPos=(i/12)*2;PPU.OBJ[i].Name=(i*3)&63;
  PPU.OBJ[i].Priority=i&3;PPU.OBJ[i].Palette=i&7;PPU.OBJ[i].Size=!!(seed&256);
  PPU.OBJ[i].HFlip=!!(seed&2);PPU.OBJ[i].VFlip=!!(seed&4);
 }
 memset(IPPU.Clip,0,sizeof(IPPU.Clip));
 unsigned clipping=(seed>>6)&3;
 if(clipping==1||clipping==2)for(unsigned plane=0;plane<2;plane++)for(unsigned bg=0;bg<5;bg++){
  IPPU.Clip[plane].Count[bg]=clipping==1?2:1;
  IPPU.Clip[plane].Left[0][bg]=clipping==1?3+bg:1;
  IPPU.Clip[plane].Right[0][bg]=clipping==1?113-bg:0;
  IPPU.Clip[plane].Left[1][bg]=139+bg;IPPU.Clip[plane].Right[1][bg]=251-bg;
 }
 d35_window_reset();d35_fixed_reset();d35_geometry_reset();
 if(clipping==3){PPU.ClipWindow2Enable[2]=1;PPU.ClipWindow2Inside[2]=!!(seed&8);Memory.FillRAM[0x212e]=Memory.FillRAM[0x212f]=4;}
 for(unsigned y=0;y<32;y++){PPU.Window2Left=19+(y*3)%80;PPU.Window2Right=221-(y*5)%72;d35_window_capture(y);}
 for(unsigned i=0;i<n;i++){((uint16_t *)GFX.Screen)[i]=BUILD_PIXEL(1,2,3);((uint16_t *)GFX.SubScreen)[i]=BUILD_PIXEL(3,2,1);}
 memset(GFX.ZBuffer,0,n);memset(GFX.SubZBuffer,1,n);
 S9xSetupOBJ();
 GFX.DB=GFX.SubZBuffer;RenderScreen(GFX.SubScreen,true,true,SUB_SCREEN_DEPTH);
 GFX.DB=GFX.ZBuffer;RenderScreen(GFX.Screen,false,false,MAIN_SCREEN_DEPTH);
 memcpy(out,GFX.Screen,n*2);memcpy(out+n*2,GFX.SubScreen,n*2);
 memcpy(out+n*4,GFX.ZBuffer,n);memcpy(out+n*5,GFX.SubZBuffer,n);
 for(unsigned y=0;y<32;y++)out[n*6+y]=GFX.OBJLines[y].RTOFlags;
 return bytes;
}
